function nativeReady(rows:readonly BuildingComponent[],leaf:Pin|undefined,programReady:boolean){return programReady&&!!leaf&&SPEC.pins.every(p=>{const a=rows.filter(c=>key(c)===key(p));return a.length===1&&a[0].city==='hannover'&&JSON.stringify(a[0].origin)===JSON.stringify(p.origin)&&nativePaintSignature(a[0])===p.geometrySignature&&leaf(a[0])===p.leafSHA256;});}
function ownerReady(rows:readonly BuildingComponent[],leaf:Pin|undefined,owner:Pin|undefined,programReady:boolean,registry:readonly any[]){return nativeReady(rows,leaf,programReady)&&!!owner&&SPEC.profiles.every(p=>{const a=rows.filter(c=>key(c)===key(p)),reg=registry.filter(r=>r.number===p.number);if(a.length!==1||reg.length!==1)return false;const c=a[0],op=c.sourceFeature?.properties?.owner_shape_patch as any;return Object.keys(p).every(k=>JSON.stringify(reg[0][k])===JSON.stringify((p as any)[k]))&&c.city===p.city&&JSON.stringify(c.origin)===JSON.stringify(p.origin)&&nativePaintSignature(c)===p.geometrySignature&&owner(c)===p.sha256&&op?.number===p.number&&op?.sourcePartId===p.sourcePartId&&op?.geometryRole===p.geometryRole&&op?.notNative===true;});}
export function hnReformierteDisplay1(c:BuildingComponent,raw:readonly BuildingComponent[],nativeLeaf:Pin|undefined,ownerLeaf:Pin|undefined,programReady:boolean,registry:readonly any[]){if(SPEC.withdrawnDerivedPartIds.includes(c.partId))return false;return !SPEC.profiles.some(p=>key(p)===key(c))||ownerReady(raw,nativeLeaf,ownerLeaf,programReady,registry);}
export function applyHNReformierte1(draw:BuildingComponent[],colors:Float32Array,frames:Float32Array,raw:readonly BuildingComponent[],nativeLeaf:Pin|undefined,ownerLeaf:Pin|undefined,programReady:boolean,registry:readonly any[]){
 if(!nativeReady(raw,nativeLeaf,programReady))return{written:0};const N=draw.reduce((n,c)=>n+c.batches.reduce((a,b)=>a+b.positions.length/3,0),0);if(colors.length!==N*4||frames.length!==N*5)return{written:0};
 if(!SPEC.pins.every(p=>{const a=draw.filter(c=>key(c)===key(p));return a.length===1&&a[0].city===p.city&&JSON.stringify(a[0].origin)===JSON.stringify(p.origin)&&nativePaintSignature(a[0])===p.geometrySignature&&nativeLeaf!(a[0])===p.leafSHA256;}))return{written:0};
 const og=ownerReady(raw,nativeLeaf,ownerLeaf,programReady,registry)&&SPEC.profiles.every(p=>{const a=draw.filter(c=>key(c)===key(p));return a.length===1&&a[0].city===p.city&&JSON.stringify(a[0].origin)===JSON.stringify(p.origin)&&nativePaintSignature(a[0])===p.geometrySignature&&ownerLeaf!(a[0])===p.sha256;});
 let at=0,written=0,nativeWrites=0,derivedWrites=0;for(const c of draw){const native=SPEC.pins.some(p=>key(p)===key(c)),derived=og&&SPEC.profiles.some(p=>key(p)===key(c));for(const[bi,b]of c.batches.entries())for(let j=0;j<b.positions.length/3;j++,at++)if(native||derived){colors[at*4+3]=2;frames.set((SPEC.frames as any)[c.partId][bi][j],at*5);written++;native?nativeWrites++:derivedWrites++;}}
 return{written,nativeWrites,derivedWrites,nativePNIChanged:false,wholeNativeCapHeld:false,outlineGroupAtomic:true};
}
